The inorder order of a BST is sorted from small to large. After storing that order, the kth smallest value is at index `k - 1`, and the kth largest value is at index `n - k`.

For example, values `[2, 4, 6, 8, 10]` with `k = 2` give largest `8` and smallest `4`. This version is easy to check, but it stores every node value.

```cpp
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int data;
 *     TreeNode *left;
 *     TreeNode *right;
 *      TreeNode(int val) : data(val) , left(nullptr) , right(nullptr) {}
 * };
 **/

class Solution {
    void inorder(TreeNode* node, vector<int>& values) {
        if (node == nullptr) {
            return;
        }

        inorder(node->left, values);
        values.push_back(node->data);
        inorder(node->right, values);
    }

public:
    vector<int> kLargesSmall(TreeNode* root, int k) {
        vector<int> values;
        inorder(root, values);

        int n = static_cast<int>(values.size());
        if (k <= 0 || k > n) {
            return {-1, -1};
        }

        return {values[n - k], values[k - 1]};
    }
};
```

Time complexity: `O(n)`.
Space complexity: `O(n)` for the vector and `O(h)` for recursion. The tree itself is not changed.

A BST can be read in two sorted directions. Normal inorder traversal, left then root then right, visits the smallest values first. Reverse inorder visits the largest values first.

The code runs one traversal for each answer and stops when its counter reaches `k`. It uses no list, so the extra memory is only the recursion stack. An empty tree or an invalid `k` returns `[-1, -1]`.

```java
import java.util.ArrayList;
import java.util.List;

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int data;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int val) { data = val; left = null, right = null }
 * }
 **/

class Solution {
    private int smallestCount;
    private int smallestValue;
    private int largestCount;
    private int largestValue;

    private void findSmallest(TreeNode node, int k) {
        if (node == null || smallestCount >= k) {
            return;
        }

        findSmallest(node.left, k);
        if (smallestCount >= k) {
            return;
        }

        smallestCount++;
        if (smallestCount == k) {
            smallestValue = node.data;
            return;
        }

        findSmallest(node.right, k);
    }

    private void findLargest(TreeNode node, int k) {
        if (node == null || largestCount >= k) {
            return;
        }

        findLargest(node.right, k);
        if (largestCount >= k) {
            return;
        }

        largestCount++;
        if (largestCount == k) {
            largestValue = node.data;
            return;
        }

        findLargest(node.left, k);
    }

    public List<Integer> kLargesSmall(TreeNode root, int k) {
        List<Integer> answer = new ArrayList<>();
        if (root == null || k <= 0) {
            answer.add(-1);
            answer.add(-1);
            return answer;
        }

        smallestCount = 0;
        largestCount = 0;
        findSmallest(root, k);
        findLargest(root, k);

        if (smallestCount < k || largestCount < k) {
            answer.add(-1);
            answer.add(-1);
            return answer;
        }

        answer.add(largestValue);
        answer.add(smallestValue);
        return answer;
    }
}
```

Time complexity: `O(n)` in the worst case because the tree can be visited twice.
Space complexity: `O(h)`, where `h` is the tree height. The input tree is only read.

Morris traversal temporarily connects a subtree back to its parent, so it can move through the tree without recursion or a stack. The normal direction gives the kth smallest value. Reversing the direction gives the kth largest value.

The temporary links are removed before each traversal finishes, so the input tree is restored. This is useful when extra memory matters, although the pointer changes make the code less simple than the stack version.

```cpp
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int data;
 *     TreeNode *left;
 *     TreeNode *right;
 *      TreeNode(int val) : data(val) , left(nullptr) , right(nullptr) {}
 * };
 **/

class Solution {
    int kthSmallest(TreeNode* root, int k) {
        TreeNode* current = root;

        while (current != nullptr) {
            if (current->left == nullptr) {
                --k;
                if (k == 0) {
                    return current->data;
                }
                current = current->right;
            } else {
                TreeNode* predecessor = current->left;
                while (predecessor->right != nullptr && predecessor->right != current) {
                    predecessor = predecessor->right;
                }

                if (predecessor->right == nullptr) {
                    predecessor->right = current;
                    current = current->left;
                } else {
                    predecessor->right = nullptr;
                    --k;
                    if (k == 0) {
                        return current->data;
                    }
                    current = current->right;
                }
            }
        }

        return -1;
    }

    int kthLargest(TreeNode* root, int k) {
        TreeNode* current = root;

        while (current != nullptr) {
            if (current->right == nullptr) {
                --k;
                if (k == 0) {
                    return current->data;
                }
                current = current->left;
            } else {
                TreeNode* successor = current->right;
                while (successor->left != nullptr && successor->left != current) {
                    successor = successor->left;
                }

                if (successor->left == nullptr) {
                    successor->left = current;
                    current = current->right;
                } else {
                    successor->left = nullptr;
                    --k;
                    if (k == 0) {
                        return current->data;
                    }
                    current = current->left;
                }
            }
        }

        return -1;
    }

public:
    vector<int> kLargesSmall(TreeNode* root, int k) {
        if (root == nullptr || k <= 0) {
            return {-1, -1};
        }

        int largest = kthLargest(root, k);
        int smallest = kthSmallest(root, k);

        if (largest == -1 || smallest == -1) {
            return {-1, -1};
        }

        return {largest, smallest};
    }
};
```

Time complexity: `O(n)` in the worst case. Each temporary link is created and removed once in each traversal.
Space complexity: `O(1)` extra space. The tree is changed briefly, then restored.

Instead of walking from an end until the counter reaches `k`, this version first records how many nodes are below every node. Then the left subtree size tells whether the wanted rank is on the left, at the current node, or on the right.

The same rank function handles both results: rank `k` gives the kth smallest, while rank `total - k + 1` gives the kth largest. The size map is extra memory, but the lookup after building it follows the tree height.

```python
# Definition for a binary tree node.
# class TreeNode(object):
#     def __init__(self, val=0, left=None, right=None):
#         self.data = val
#         self.left = left
#         self.right = right

class Solution:
    def kLargestSmall(self, root, k):
        if root is None or k <= 0:
            return [-1, -1]

        sizes = {}

        def build_sizes(node):
            if node is None:
                return 0
            size = 1 + build_sizes(node.left) + build_sizes(node.right)
            sizes[node] = size
            return size

        def subtree_size(node):
            return 0 if node is None else sizes[node]

        def find_by_rank(node, rank):
            while node is not None:
                left_size = subtree_size(node.left)

                if rank == left_size + 1:
                    return node.data
                if rank <= left_size:
                    node = node.left
                else:
                    rank -= left_size + 1
                    node = node.right

            return -1

        total = build_sizes(root)
        if k > total:
            return [-1, -1]

        smallest = find_by_rank(root, k)
        largest = find_by_rank(root, total - k + 1)
        return [largest, smallest]
```

Time complexity: `O(n + h)` for building the sizes and finding both ranks.
Space complexity: `O(n)` for the subtree size map, plus `O(h)` for the recursive size building. The original tree is not changed.

class Solution {
public:
    // Helper function to perform an in-order traversal of the BST
    void inorderTraversal(TreeNode* node, vector<int>& values) {
        if (node) {
            inorderTraversal(node->left, values);
            values.push_back(node->data);
            inorderTraversal(node->right, values);
        }
    }

    vector<int> kLargesSmall(TreeNode* root, int k) {
        // Vector to store the node values
        vector<int> values;
        // Perform in-order traversal and collect values
        inorderTraversal(root, values);

        // Find the kth smallest and kth largest values
        int kth_smallest = values[k - 1];
        int kth_largest = values[values.size() - k];

        return {kth_smallest, kth_largest};
    }
};

