    int inorder(TreeNode* root, int &k) {
        if (root == NULL)
            return -1;

        int left = inorder(root->left, k);
        if (left != -1)
            return left;

        k--;
        if (k == 0)
            return root->data;

        return inorder(root->right, k);
    }

    int revinorder(TreeNode* root, int &k) {
        if (root == NULL)
            return -1;

        int right = revinorder(root->right, k);
        if (right != -1)
            return right;

        k--;
        if (k == 0)
            return root->data;

        return revinorder(root->left, k);
    }

    vector<int> kLargesSmall(TreeNode* root, int k) {
        int k1 = k, k2 = k;

        int smallest = inorder(root, k1);
        int largest = revinorder(root, k2);

        return {smallest,largest};
    }
};
